static void Bonechiller(){Creature actor;Player player;actor.victim=&player;auto frame=Poisoned<npc_bloodsnow_frostmane_bonechiller>(&actor);frame->Reset();actor.hp=40;uint32 damage=10;frame->DamageTaken(&player,damage,0);Require(frame->events.scheduled.count(EVENT_WATER_ELEMENTAL)==1&&damage==10,"Fresh/reset native phase must schedule the authored elemental for a player hit");frame->DamageTaken(&player,damage,0);Require(frame->events.scheduled.size()==1,"Repeated hits cannot duplicate the elemental event");frame->UpdateAI(999);Require(casts.empty(),"Authored1s elemental delay retained");frame->UpdateAI(1);Require(casts.size()==1&&casts[0].spell==SPELL_SUMMON_WATER_ELEMENTAL,"Original event/helper summons the actual elemental spell");Unit pet,guardian,npc;pet.owner=&player;guardian.owner=&pet;for(Unit*attacker:{static_cast<Unit*>(&player),&pet,&guardian,&npc,static_cast<Unit*>(nullptr)}){frame->Reset();damage=10;frame->DamageTaken(attacker,damage,0);Require(damage==(attacker==&npc?0u:10u),"Player/pet/guardian keep damage;native unrelated NPC floor/null-attacker semantics retained");}frame->Reset();actor.hp=100;damage=100;frame->DamageTaken(&guardian,damage,0);Require(damage==100&&frame->events.scheduled.empty(),"Original current-health threshold does not force an elemental before a one-hit kill");frame->Reset();actor.hp=40;frame->DamageTaken(&player,damage,0);Require(frame->events.scheduled.size()==1,"A new reset phase can schedule again");}
static void Viletongue(){Creature actor;Player attacker;actor.victim=&attacker;actor.entry=NPC_VILETONGUE_SKIRMISHER;actor.hp=40;auto frame=Poisoned<npc_viletongue_sauroks>(&actor);frame->Reset();uint32 damage=10;frame->DamageTaken(&attacker,damage,0);Require(casts.size()==1&&casts[0].source==&actor&&casts[0].target==&attacker&&casts[0].spell==SPELL_VILETONGUE_STING,"Fresh poison latch permits the original low-health sting");frame->DamageTaken(&attacker,damage,0);Require(casts.size()==1,"Accepted sting consumes exactly once");frame->Reset();ResetObservations();frame->DamageTaken(nullptr,damage,0);Require(casts.empty()&&!frame->poisoned,"Missing attacker cannot consume poison");castResult=12;frame->DamageTaken(&attacker,damage,0);Require(casts.size()==1&&!frame->poisoned,"Rejected/busy cast request retains a retry");castResult=SPELL_CAST_OK;castReentry=[&]{frame->DamageTaken(&attacker,damage,0);};frame->DamageTaken(&attacker,damage,0);Require(casts.size()==2&&frame->poisoned,"Accepted retry admits no duplicate during reentrant casting");frame->Reset();ResetObservations();Unit pet;pet.owner=&attacker;frame->DamageTaken(&pet,damage,0);Require(casts.size()==1&&casts[0].target==&pet,"Original offensive target remains the actual pet attacker");frame->Reset();actor.hp=100;ResetObservations();frame->DamageTaken(&attacker,damage,0);Require(casts.empty(),"Above-threshold hit cannot consume poison");actor.hp=40;actor.entry=0;frame->DamageTaken(&attacker,damage,0);Require(casts.empty(),"Other Saurok entries retain no-sting admission");}
static void Gargoyle(){Creature actor,target,other;actor.ownerGuid={77};actor.victim=&target;target.guid={2};other.guid={3};auto frame=Poisoned<npc_ebon_gargoyleAI>(&actor);frame->InitializeAI();spatial={&target};frame->UpdateAI(1);Require(frame->targetCheckTime==1&&frame->despawnTimer==0&&frame->mainTargetGUID==target.guid&&frame->checkTarget,"Fresh gargoyle starts its actual clock and acquires the original owner's marked target");actor.victim=&other;frame->UpdateAI(1999);Require(frame->targetCheckTime==2000&&searches==1,"Original strictly-greater-than2s target recheck admission retained");frame->UpdateAI(1);Require(frame->targetCheckTime==0&&searches==2,"Target mismatch re-arms scanning at authored window");actor.ownerGuid.Clear();frame->InitializeAI();Require(frame->despawnTimer==0&&frame->targetCheckTime==0&&!frame->checkTarget&&!frame->mainTargetGUID,"Missing owner early return cannot preserve poison or an earlier dismissal clock");Player owner;actor.owner=&owner;actor.ownerGuid=owner.GetGUID();frame->InitializeAI();SpellInfo dismissal;dismissal.Id=50515;frame->SpellHit(&owner,&dismissal);Require(frame->despawnTimer==4000,"Actual owner dismissal keeps4s flight clock");frame->UpdateAI(3999);Require(!despawns,"Dismissal cannot finish early");frame->UpdateAI(1);Require(despawns==1,"Dismissal still despawns at authored4s");frame->InitializeAI();Require(frame->despawnTimer==0&&frame->targetCheckTime==0,"Reinitialization resets both clocks");}
static void Avatar(){Creature actor,add;InstanceScript instance;maiden=&add;auto frame=std::make_unique<AvatarFrame>(&actor);frame->instance=&instance;frame->Queue();frame.reset();actor.PumpCombat(499);Require(!zones&&!frames,"Original combat queue delay retained before AI retirement witness");actor.PumpCombat(1);Require(!zones&&!frames,"Expired source AI cannot touch its retired instance/summon state");frame=std::make_unique<AvatarFrame>(&actor);frame->instance=&instance;frame->Queue();actor.PumpCombat(500);Require(zones==1&&frames==1,"Live source retains Maiden combat admission and encounter frame");frame->Queue();actor.PumpCombat(500);Require(zones==1&&frames==2,"Already-fighting Maiden keeps only original encounter frame");maiden=nullptr;frame->Queue();actor.PumpCombat(500);Require(frames==2,"Missing Maiden skips optional request");maiden=&add;frame->Queue();actor.KillAllDelayedCombats();frame.reset();actor.PumpCombat(500);Require(frames==2,"Original Unit-owned queue cancellation retained");}
static void Rhyme(){Creature caster;Player target;spell_summoning_rhyme_aura_AuraScript script;script.target=&target;Effect effect;script.PeriodicTick(&effect);Require(casts.empty()&&speeches.empty(),"Lost summoning caster cannot dereference or emit dialogue");script.caster=&target;script.PeriodicTick(&effect);Require(speeches.empty(),"Non-creature caster keeps original no-dialogue admission");script.caster=&caster;Require(script.Validate(nullptr),"Original45930child validation retained");script.validate=false;Require(!script.Validate(nullptr),"Missing child still fails native validation");script.validate=true;for(uint32 tick=1;tick<=3;++tick){effect.tick=tick;script.PeriodicTick(&effect);}Require(speeches.size()==3&&textRecipient==&target&&casts.size()==1&&casts[0].source==&target&&casts[0].target==&target&&casts[0].spell==45930&&script.removed,"All3targeted speeches/first-tick child andthird-tick aura removal retained");}
static void Drain(){Player caster;Creature target;spell_drain_fel_enegry_AuraScript script;script.target=&target;script.OnRemove(nullptr,0);Require(casts.empty()&&!despawns,"Missing player cannot grant Codex or force target cleanup");script.caster=&target;script.OnRemove(nullptr,0);Require(casts.empty()&&!despawns,"Non-player caster keeps original no-reward path");script.caster=&caster;script.OnRemove(nullptr,0);Require(casts.size()==1&&casts[0].source==&caster&&casts[0].target==&caster&&casts[0].spell==SPELL_THE_CODEX_OF_XERRATH&&despawns==1&&despawnDelay==3000,"Original real-player self Codex request and3s target cleanup retained");ResetObservations();script.target=&caster;script.OnRemove(nullptr,0);Require(casts.size()==1&&!despawns,"Non-creature recipient retains no forced despawn");}
static void Lilet(){Creature actor;auto frame=Poisoned<npc_lilet_lunarhAI>(&actor);frame->UpdateAI(999999);Require(speeches.empty(),"Unstarted actor cannot consume uninitialized dialogue state");auto departing=std::make_unique<Player>();departing->guid={88};players[88]=departing.get();frame->IsSummonedBy(departing.get());frame->UpdateAI(12999);Require(speeches.empty(),"Authored first13s delay retained");players.erase(88);departing.reset();frame->UpdateAI(1);Require(speeches.empty(),"Disconnected/destroyed owner cannot be dereferenced by delayed speech");Player connected;connected.guid={88};players[88]=&connected;frame->UpdateAI(16000);Require(speeches.size()==1&&speeches.back().first==1&&speeches.back().second==connected.guid,"Same legitimate reconnected GUID resolves its actual next speech");connected.map=2;frame->UpdateAI(16000);Require(speeches.size()==1,"Different map owner cannot receive actor-local speech");connected.map=1;frame->IsSummonedBy(&connected);speeches.clear();frame->UpdateAI(13000);for(uint32 i=0;i<3;++i)frame->UpdateAI(16000);Require(speeches.size()==4,"A new actual summon context retains4speech sequence");for(uint32 i=0;i<4;++i)Require(speeches[i].first==i&&speeches[i].second==connected.guid,"Target identity and native dialogue order retained");frame->UpdateAI(999999);Require(speeches.size()==4,"Completed dialogue remains finite");frame->IsSummonedBy(&actor);speeches.clear();frame->UpdateAI(13000);Require(speeches.empty(),"Non-player summoner retains original silent sequence");}
static void Alluradel(){Creature actor,first,second;first.guid={21};second.guid={22};actor.victim=&first;boss_mistress_alluradel frame(&actor);frame.Reset();ResetObservations();frame.UpdateAI(1);Require(removals==1&&frame.checktimer==500&&frame.tankGUID==first.guid,"First live Sadist check captures actual tank and authored500ms clock");actor.victim=&second;frame.UpdateAI(100);Require(removals==1&&frame.checktimer==400,"Each server tick cannot erase the intended interval");frame.UpdateAI(400);Require(removals==2&&frame.tankGUID==second.guid&&frame.checktimer==500,"Tank transition removes only native Sadist proc at original interval");frame.UpdateAI(500);Require(removals==2&&frame.checktimer==500,"Unchanged tank still advances finite poll clock");actor.casting=true;frame.UpdateAI(1000);Require(frame.checktimer==500,"Casting gate preserves polling deferral");actor.casting=false;actor.aura=false;frame.UpdateAI(1000);Require(frame.checktimer==500,"Missing controller aura preserves native no-check admission");frame.Reset();Require(frame.checktimer==0&&!frame.tankGUID,"Reset cannot retain a previous tank checkpoint or clock");}
template<class F>static void RunScarab(bool outdoor){world.values.clear();world.reads=0;gameEvents.active={78,EVENT_CALL_OF_THE_SCARAB};WorldDatabase.writes=CharacterDatabase.writes=0;world.values[WS_SCORE_CALL_OF_THE_SCARAB_ALLINCE]=10;world.values[WS_SCORE_CALL_OF_THE_SCARAB_HORDE]=20;F frame;if(outdoor)frame.HandleGameEventStart(EVENT_CALL_OF_THE_SCARAB);else frame.Initialize();std::array<Player,3>participants;for(auto&player:participants)frame.map.players.push_back(&player);Require(frame.CurrectAllianceScore==10&&frame.CurrectHordeScore==20,"Native initial faction caches retain their own score");frame.Update(2000);for(auto&p:participants)Require(p.worldstates.empty(),"Unchanged snapshot must not repeatedly broadcast a different faction's cache");world.values[WS_SCORE_CALL_OF_THE_SCARAB_ALLINCE]=15;world.values[WS_SCORE_CALL_OF_THE_SCARAB_HORDE]=25;frame.Update(1999);for(auto&p:participants)Require(p.worldstates.empty(),"Original2s poll interval retained");frame.Update(1);for(auto&p:participants){Require(p.worldstates==std::vector<std::pair<uint32,uint32>>{{12953,15},{12952,25}},"Every participant receives both changed native score values");p.worldstates.clear();}Require(frame.CurrectHordeScore==25&&frame.CurrectAllianceScore==15,"Caches advance after full broadcast to correct faction values");world.values[WS_SCORE_CALL_OF_THE_SCARAB_HORDE]=40;frame.Update(2000);for(auto&p:participants){Require(p.worldstates==std::vector<std::pair<uint32,uint32>>{{12952,40}},"Single faction update reaches every participant once");p.worldstates.clear();}frame.Update(2000);for(auto&p:participants)Require(p.worldstates.empty(),"Settled score does not flood unchanged packets");world.values[WS_SCORE_CALL_OF_THE_SCARAB_ALLINCE]=0;world.values[WS_SCORE_CALL_OF_THE_SCARAB_HORDE]=0;gameEvents.active.clear();frame.Update(2000);for(auto&p:participants)Require(p.worldstates==std::vector<std::pair<uint32,uint32>>{{12953,0},{12952,0}},"Actual native zeroed scores clear all participants after event ends");Require(!WorldDatabase.writes&&!CharacterDatabase.writes,"Ordinary score regression does not enter winner/database cleanup branches");}
static void CloneWeapon(){struct Entry{uint32 spell,slot,equipment;};Entry entries[]={{SPELL_COPY_WEAPON_AURA,0,15},{SPELL_COPY_WEAPON_2_AURA,0,15},{SPELL_COPY_WEAPON_3_AURA,0,15},{SPELL_COPY_OFFHAND_AURA,1,16},{SPELL_COPY_OFFHAND_2_AURA,1,16},{SPELL_COPY_RANGED_AURA,2,17}};Creature source,target;std::array<uint32,6>original{1001,0x00220011,1002,0x00440033,1003,0x00660055},copied{2001,0x00880077,2002,0x00aa0099,2003,0x00cc00bb};
for(auto e:entries){source.virtualItems=copied;target.virtualItems=original;spell_gen_clone_weapon_auraScript script;script.info.Id=e.spell;script.caster=&source;script.target=&target;Require(script.Validate(nullptr),"All six original child spell validations retained");script.OnApply(nullptr,AURA_EFFECT_HANDLE_REAL);auto expected=original;expected[e.slot*2]=copied[e.slot*2];expected[e.slot*2+1]=copied[e.slot*2+1];Require(target.virtualItems==expected,"NPC clone must copy actual native two-field slot and both appearance halves");script.caster=nullptr;script.OnRemove(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems==original,"Caster loss cannot prevent exact item/appearance/visual restoration of the correct slot");script.OnRemove(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems==original,"Repeated final removal cannot consume an absent snapshot");
spell_gen_clone_weapon_auraScript missing;missing.info.Id=e.spell;missing.target=&target;missing.OnApply(nullptr,AURA_EFFECT_HANDLE_REAL);missing.OnRemove(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems==original,"Failed initial apply cannot replace an untouched weapon with a zero or invalid saved item");
spell_gen_clone_weapon_auraScript reapplied;reapplied.info.Id=e.spell;reapplied.caster=&source;reapplied.target=&target;reapplied.OnApply(nullptr,AURA_EFFECT_HANDLE_REAL);reapplied.OnRemove(nullptr,32);Require(target.virtualItems==original,"Native reapply removal restores the real original snapshot");source.virtualItems[e.slot*2]=3000;reapplied.OnApply(nullptr,32);reapplied.OnApply(nullptr,32);Require(target.virtualItems[e.slot*2]==3000,"Reapply refreshes source visual without overwriting original checkpoint");reapplied.OnRemove(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems==original,"Final removal after repeated applies/reapply pair restores first original fields");
Player player;Item equipped{4444};spell_gen_clone_weapon_auraScript playerClone;playerClone.info.Id=e.spell;playerClone.caster=&player;playerClone.target=&target;playerClone.OnApply(nullptr,AURA_EFFECT_HANDLE_REAL);playerClone.OnRemove(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems==original,"Player without the equipped slot keeps original no-copy behavior and target appearance");player.items[e.equipment]=&equipped;playerClone.OnApply(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems[e.slot*2]==4444&&target.virtualItems[e.slot*2+1]==0,"Actual equipped player item keeps original base-item clone semantics");playerClone.OnRemove(nullptr,AURA_EFFECT_HANDLE_REAL);Require(target.virtualItems==original,"Player clone removal preserves complete target appearance metadata");}
}
int main(int argc,char**argv){try{Require(argc==2,"Case required");ResetObservations();uint32 which=uint32(std::stoul(argv[1]));switch(which){case 0:Bonechiller();break;case 1:Viletongue();break;case 2:Gargoyle();break;case 3:Avatar();break;case 4:Rhyme();break;case 5:Drain();break;case 6:Lilet();break;case 7:Alluradel();break;case 8:SCARAB_CASES break;case 9:CloneWeapon();break;default:throw std::runtime_error("Unknown case");}std::cout<<"PASS complete production fourth-batch case "<<which<<":controlled external endpoints;native queues/lookup/bindings and full client checks separate\n";return 0;}catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
